/* 危险操作保持红色语义 */
.menu_button.danger {
    color: var(--mf-red);
}

@media (hover: hover) and (pointer: fine) {
    #delete_button:hover,
    #reset_button:hover {
        color: var(--mf-red);
        border-color: var(--mf-red);
    }
}

/* ---------- 角色列表 / 卡片条目 ---------- */
.character_select,
.group_select,
.character_select_container,
.entity_block {
    border-radius: 0;
    border-bottom: 1px dashed var(--mf-dash);
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .character_select:hover,
    .group_select:hover {
        background-color: var(--mf-bg-hover);
    }
}

.character_select:active,
.group_select:active {
    background-color: var(--mf-line-2);
}

.character_select:focus-visible,
.group_select:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: -1px;
}

.character_name_block .ch_name,
.character_name_block .character_name {
    color: var(--mf-ink);
    font-weight: 700;
    font-size: 12.5px;
}

.character_name_block .character_file,
.character_name_block .group_file {
    color: var(--mf-ink-4);
    font-size: 11px;
}

/* 当前选中角色：浅绿条 + 左侧绿竖线 */
.character_select.is_selected,
.group_select.is_selected {
    background-color: var(--mf-bg-soft);
    box-shadow: inset 3px 0 0 var(--mf-title);
}

/* ---------- 弹出菜单 / 弹层 ---------- */
#options,
.options-content,
.popup,
.dialogs,
#dialogue_popup {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.6);
    color: var(--mf-ink);
}

#options .options-content a,
#options .options-content .interactable {
    border-radius: 0;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #options .options-content a:hover,
    #options .options-content .interactable:hover {
        background-color: var(--mf-bg-hover);
        color: var(--mf-green);
    }
}

#options .options-content a:active,
#options .options-content .interactable:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

/* 弹窗标题 */
.dialogue_popup_text h2,
.popup_title,
.dialogue_popup_controls h3 {
    color: var(--mf-ink);
}

/* ---------- 提示消息：白底 + 左侧 3px 色条 ----------
 * 酒馆原生给 .toast-success 之类铺了语义底色，权重比 #toast-container > div 高；
 * 只改边框会变成「绿底 + 我的边」的拼接感，所以整块接管。
 * 原生图标是透明底白色 PNG，放白底上等于消失 —— 关掉 background-image 并收回左侧内边距。
 */
body #toast-container > div.toast {
    background-color: var(--mf-paper);
    background-image: none;
    border: 1px solid var(--mf-line);
    border-left: 3px solid var(--mf-title-2);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.6);
    color: var(--mf-ink);
    font-size: 12px;
    opacity: 1;
    padding: 8px 10px 8px 12px;
    width: 300px;
}

body #toast-container > div.toast.toast-success {
    border-left-color: var(--mf-green);
}

body #toast-container > div.toast.toast-error {
    border-left-color: var(--mf-red);
}

body #toast-container > div.toast.toast-warning {
    border-left-color: var(--mf-accent);
}

body #toast-container > div.toast.toast-info {
    border-left-color: var(--mf-link);
}

/* ---------- 设置页分组标题：绿标题条 ---------- */
#user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    background-color: var(--mf-titlebar-b);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-title);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
}

@media (hover: hover) and (pointer: fine) {
    #user-settings-block h4:hover,
    #extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
    #extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
        filter: none;
        background-image: none;
        background-color: var(--mf-bg-hover);
        color: var(--mf-green-deep);
    }
}

/*
 * 提示词管理器：类名带 completion_ 前缀（聊天补全）和不带前缀（文本补全）两套，
 * 用 [class*=] 一次覆盖；酒馆自己的规则是 #id #id 级别，这里必须 !important 才压得住。
 */
[class*="prompt_manager_prompt"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--mf-ink) !important;
}

/* 启用中的开关用深绿 */
[class*="prompt_manager_prompt"]:not([class*="prompt_manager_prompt_disabled"]) .prompt-manager-toggle-action {
    color: var(--mf-green) !important;
}

/* 禁用项名称酒馆默认用 white30a（深色主题专用），白底上等于隐形 */
[class*="prompt_manager_prompt_disabled"] {
    border-color: var(--mf-line) !important;
    background-color: var(--mf-paper-2) !important;
}

[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--mf-ink-5) !important;
}

/* 表头「名称 / Token」那行同样是 white50a */
[class*="prompt_manager_header"] {
    color: var(--mf-ink-4) !important;
}

/* 图标上的黑色投影是给深色底做的，浅底上去掉更干净 */
[class*="prompt_manager_prompt"] span span span,
[class*="prompt_manager_header_advanced"] span {
    filter: none;
}

/* 选中态：酒馆默认拿 SmartThemeQuoteColor 铺深色块，统一改成浅绿 */
.macroBrowser .macro-sort-btn.active,
.macroBrowser .macro-item.selected,
#rm_print_characters_block.group_overlay_mode_select .character_select.character_selected,
#bg_tabs .bg_tabs_list .bg_tab_button.ui-tabs-active {
    background-color: var(--mf-bg-soft);
    border-color: var(--mf-line);
    color: var(--mf-ink);
}

/* ---------- 标签 / 徽章：小方块，浅绿底 ---------- */
.tag,
.tag_name,
.character_version,
.character_tag {
    border-radius: 0;
    background-color: var(--mf-bg-soft);
    border: 1px solid var(--mf-line-2);
    color: var(--mf-ink-2);
    font-size: 11px;
}

@media (hover: hover) and (pointer: fine) {
    .tag:hover,
    .character_tag:hover {
        background-color: var(--mf-bg-hover);
        border-color: var(--mf-line);
        color: var(--mf-green);
    }
}

.tag:active,
.character_tag:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

/* ---------- 内建深色残留：把拿 quote color / 灰阶当底的地方拉回浅色 ----------
 * 酒馆这套组件是按「深色半透明底」写的，浅色门户上会变成一块块深灰巧克力：
 *   · #user-settings-block h4 与主题同特异性、且酒馆样式表在后生效 → 加 body 前缀
 *   · select2 多选标签（世界书「已启用条目」）底色固定 rgba(0,0,0,.5)
 *   · .world_entry / .wi-card-entry 的边框取 currentColor，正文深色就成了黑框
 */

body #user-settings-block h4 {
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    background-color: var(--mf-titlebar-b);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-title);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
}

@media (hover: hover) and (pointer: fine) {
    body #user-settings-block h4:hover {
        background-image: none;
        background-color: var(--mf-bg-hover);
        color: var(--mf-green-deep);
    }
}

/* select2 多选标签：世界书「已启用条目」、角色标签都在这里。
 * 酒馆用 `.select2-container … .select2-selection__choice`(0,3,0) 铺 var(--black30a)，
 * 且它的样式表晚于 #custom-style 生效，所以这里加 body 提到 (0,3,1) 才压得住。 */
body .select2-container .select2-selection--multiple .select2-selection__choice,
body .select2-selection__choice {
    background-color: var(--mf-bg-soft);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink);
}

body .select2-container .select2-selection__choice__display {
    color: var(--mf-ink) !important;
    padding-left: 2px;
    padding-right: 2px;
}

body .select2-container .select2-selection__choice__remove {
    color: var(--mf-ink-3);
    background-color: transparent;
    border-right: 1px solid var(--mf-line-2);
}

@media (hover: hover) and (pointer: fine) {
    body .select2-container .select2-selection__choice__remove:hover {
        background-color: var(--mf-line-2);
        color: var(--mf-red);
    }
}

/* 世界书条目卡片：黑框改绿框，白底 */
.wi-card-entry {
    border-color: var(--mf-line);
    background-color: var(--mf-paper);
    border-radius: 0;
}

body .world_entry {
    border-color: var(--mf-line);
}

/* 世界书条目的启用开关 */
.world_entry .killSwitch.fa-toggle-on {
    color: var(--mf-green);
}

/* 酒馆内建的「已选中」行底色写死成深红 rgb(102,0,0) */
body #chat .mes.selected {
    background-color: var(--mf-bg-soft);
    outline: 1px solid var(--mf-line);
}


/*
 * 主页（欢迎面板）：按 mikufans.cn/index.html 的首页版式重排。
 *
 * 原站首页是「白底 + 定宽双区」的 DedeCMS 版面：
 *   .header .top   站名字标 + banner 长条 + 右侧四个 rlink 小按钮（78×21）
 *   .nav           32px 主导航条（极淡灰绿渐变、黑字、项间距 17/18px、hover #8A0808）
 *   .search        浅色搜索条（输入框 + 红色按钮 + 热门标签）
 *   .pleft         左栏 692px：banner 长图 + .picnews .e1 图文格（120×90 图，横向排列）
 *   .pright        右栏 260px：若干 dl.tbox 侧栏块
 *
 * 酒馆的欢迎面板是单列，能对上的部分：
 *   面板底板 → 白纸 + 1px 实线框（原站 .wlistbox）
 *   页头     → .header .top（白底、底边虚线）
 *   分类行   → .nav（浅绿渐变导航条、黑字）
 *   快捷入口 → .rlink（78×21 小方块）
 *   长条     → .pleft 顶部那张 mad.png「动画专区」（31px）
 *   列表     → .picnews .e1（横向 120×90 图格，标题居中）
 *   更多     → .dede_pages 分页条
 *
 * 酒馆 1.19 的「最近聊天」组件结构：
 *   .recentChat > .avatar + .recentChatInfo
 *   .recentChatInfo > .chatNameContainer(.chatName/.chatDate/.chatActions)
 *                   + .chatMessageContainer(.chatMessage/.chatStats)
 * 用 display: contents 摊平两个容器，让各层直接成为图格的 flex 子项。
 *
 * 注意：酒馆自带的 welcome.css 用的是 `.welcomeRecent .recentChatList .recentChat …`
 * （三到四级类），这里必须保持同样的层级深度才压得住，不要简化选择器。
 */

/*
 * 首页双栏：原站是 .pleft（692 左主区）+ .pright（260 右栏）的定宽版面。
 * 酒馆的 DOM 是「欢迎面板 + 若干消息」平铺在 #chat 里，
 * 所以用网格把欢迎面板钉在左列、消息块全部落到右列竖直堆叠，
 * 高度仍由内容决定（align-items: start），不做等高拉伸。
 *
 * 只在欢迎页存在时生效：一旦开始聊天，welcomePanel 消失，#chat 自动回到单栏。
 */
#chat:has(.welcomePanel) {
    display: grid;
    /* 原站 .pleft 692 + .pright 260；928 - 260 - 8 = 660，正好放 5 个 126px 图格 */
    grid-template-columns: minmax(0, 1fr) 260px;
    align-content: start;
    align-items: start;
    column-gap: 8px;
}

#chat:has(.welcomePanel) > .welcomePanel {
    grid-column: 1;
    /* 隐式网格没有行数上界，给一个足够大的 span 让左列不被消息挤断 */
    grid-row: 1 / span 999;
    margin: 0;
}

#chat:has(.welcomePanel) > .mes {
    grid-column: 2;
    width: 100%;
    margin: 0 0 6px;
}



/* 右栏只有 260px：标题条给足高度，让「角色名 + 时间」能排成两行而不溢出 */
#chat:has(.welcomePanel) > .mes[is_user="false"] .ch_name,
#chat:has(.welcomePanel) > .mes[is_user="true"] .ch_name {
    min-height: 42px;
    padding: 3px 6px 3px 34px;
    gap: 0 4px;
    flex-wrap: wrap;
    align-content: center;
}

#chat:has(.welcomePanel) > .mes .mesAvatarWrapper {
    top: 3px;
    left: 6px;
    width: 20px;
    height: 20px;
}

#chat:has(.welcomePanel) > .mes .mesAvatarWrapper .avatar {
    width: 20px;
    height: 20px;
}

#chat:has(.welcomePanel) > .mes[is_user="false"] .name_text {
    font-size: 12px;
    letter-spacing: 0;
}

#chat:has(.welcomePanel) > .mes .timestamp {
    margin-left: 4px;
    font-size: 10.5px;
}

#chat:has(.welcomePanel) > .mes[is_user="false"] .mes_text {
    padding: 6px 8px 7px;
    font-size: 12.5px;
    line-height: 1.65;
}

#chat:has(.welcomePanel) > .mes[is_user="true"] .mes_text {
    padding: 1px 0 0 14px;
    font-size: 12.5px;
}

#chat:has(.welcomePanel) > .mes[is_user="false"] .mes_block::after {
    margin: 0 8px 6px;
    font-size: 10.5px;
    line-height: 1.5;
}

/* ---------- 面板底板：白纸 + 1px 实线 ---------- */
.welcomePanel {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: none;
    padding: 0;
    margin: 0 0 4px;
}

/* ---------- 页头：.header .top ---------- */
.welcomePanel .welcomeHeaderTitle {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 8px 6px;
    border-bottom: 1px dashed var(--mf-line-2);
}

.welcomePanel .welcomeHeaderLogo {
    width: 21px;
    height: 21px;
    border-radius: 0;
    flex: 0 0 auto;
    object-fit: contain;
}

.welcomePanel .welcomeHeaderVersionDisplay {
    font-size: 13px;
    font-weight: 700;
    color: var(--mf-title);
    letter-spacing: 1px;
}

/* 页头右侧的圆角小按钮 → 原站 rlink 的方角小块 */
.welcomePanel .welcomeHeaderTitle .mes_button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 21px;
    margin: 0;
    padding: 0;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: var(--mf-bg-soft);
    background-image: linear-gradient(180deg, #FBFCF8 0%, #EDF2E6 100%);
    color: #777777;
    font-size: 11px;
    opacity: 1;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeHeaderTitle .mes_button:hover {
        background-image: linear-gradient(180deg, #FFFFFF 0%, #E3EDD8 100%);
        border-color: var(--mf-line);
        color: var(--mf-title);
    }
}

.welcomePanel .welcomeHeaderTitle .mes_button:active {
    background-image: none;
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeHeaderTitle .mes_button:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 1px;
}

/* ---------- 分类行：.nav 主导航条（黑字、渐变底、上下压线） ---------- */
.welcomePanel .welcomeHeader {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    min-height: 30px;
    padding: 0 8px;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0;
    color: #000000;
    /* 原站 nav 底图是 nav-bg.gif，整体是灰白，只有极轻的偏绿，这里用中性灰渐变 */
    background-color: #EFEFEF;
    background-image: linear-gradient(180deg, #FBFBFB 0%, #F0F0F0 55%, #E7E7E7 100%);
    border-top: 1px solid var(--mf-line);
    border-bottom: 1px solid var(--mf-line);
}

/* 原站 nav 项前面没有色块，这里也去掉，只留文字 */
.welcomePanel .welcomeHeader::before {
    content: none;
}

.welcomePanel .welcomeShortcuts {
    display: flex;
    align-items: center;
    gap: 3px;
    margin-left: auto;
}

/* 快捷入口：原站 .rlink li a 的 78×21 方块 */
.welcomePanel .welcomeShortcuts .menu_button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 3px;
    min-width: 78px;
    height: 21px;
    padding: 0 5px;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: #FBFBFB;
    background-image: linear-gradient(180deg, #FBFBFB 0%, #EDEDED 100%);
    color: #777777;
    font-size: 12px;
    font-weight: 400;
    letter-spacing: 0;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeShortcuts .menu_button:hover {
        background-image: linear-gradient(180deg, #FFFFFF 0%, #E6E6E6 100%);
        border-color: #C0C0C0;
        color: var(--mf-title);
    }
}

.welcomePanel .welcomeShortcuts .menu_button:active {
    background-image: none;
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeShortcutsSeparator {
    display: none;
}

/* ---------- 内容区 ---------- */
.welcomePanel .welcomeRecent {
    padding: 0 0 6px;
    background-color: var(--mf-paper);
}

/*
 * 顶部频道横幅：直接用原站首页 .pleft 顶部那张 mad.png（663×31）。
 * 「动画/音乐/游戏_動画/音楽/ゲーム_Animation/Music/Game」是原图里的手写体，
 * 文字用 CSS 复刻不出来，所以按原样内联位图（见 tools/make-assets-css.cjs）。
 */
.welcomePanel .welcomeRecent::before {
    content: "";
    display: block;
    height: 31px;
    margin: 8px 8px 8px;
    background-image: var(--mf-banner);
    background-repeat: no-repeat;
    background-position: left center;
    background-size: 100% 100%;
    border: none;
}

/* ---------- 列表：.picnews .e1 横向图格 ----------
 * 原站 .e1 { padding-top:8px; padding-bottom:8px }，li 之间没有额外 gap，
 * 行距完全由 li 的固定高度（136px）撑出来。
 */
.welcomePanel .welcomeRecent .recentChatList {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: 0;
    padding: 8px 0;
}

/* 原站 .e1 li：126×136，左内距 5px，居中，overflow hidden */
.welcomePanel .welcomeRecent .recentChatList .recentChat {
    position: relative;
    display: flex;
    flex-direction: column;
    flex: 0 0 126px;
    max-width: 126px;
    align-items: center;
    box-sizing: border-box;
    height: 136px;
    overflow: hidden;
    padding: 0 0 0 5px;
    border: none;
    border-radius: 0;
    background-color: transparent;
    text-align: center;
    transition: none;
}

/* 折叠的条目必须真的不占位，否则「更多」按钮前会留一大片空白 */
.welcomePanel .welcomeRecent .recentChatList .recentChat.hidden {
    display: none;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within {
    outline: 1px dotted var(--mf-green);
    outline-offset: -1px;
}

/* 缩略图：原站 .e1 li a img —— 120×90 内容 + 2px 白衬 + 1px #E3E3E3 框 = 124×94 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
    flex: 0 0 auto;
    align-self: center;
    width: 124px;
    height: 94px;
    margin: 0;
    box-sizing: border-box;
    padding: 2px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-frame);
    border-radius: 0;
    overflow: hidden;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .avatar {
        border-color: #999999;
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

/* 内容容器摊平，让标题/日期直接成为图格的子项 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatInfo {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    min-width: 0;
    gap: 0;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatNameContainer,
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessageContainer {
    display: contents;
}

/* 标题：原站 .e1 li a span { line-height:17px; padding-top:6px }，12px 继承字号，两行 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
    flex: none;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
    width: 100%;
    margin: 0;
    padding: 6px 0 0;
    font-size: 12px;
    font-weight: 400;
    line-height: 17px;
    color: #1C1C1C;
    text-align: center;
    white-space: normal;
    overflow-wrap: anywhere;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName .characterName {
    font-weight: 700;
    color: var(--mf-title);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName > span {
    font-size: 11px;
    font-weight: 400;
    color: var(--mf-ink-4);
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatName,
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatName .characterName {
        color: var(--mf-brand-pink);
    }
}

/* 图格里不放摘要（原站 e1 只有图 + 标题） */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessage {
    display: none;
}

/* 原站 e1 图格里只有图 + 标题两行，格高 136 已被 94 + 6 + 34 占满，日期收掉 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatDate {
    display: none;
}

/* 原站 e1 图格里只有图 + 标题，消息数/体积这种元信息在窄格里只会破坏比例，直接收掉 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats {
    display: none;
}

/* 操作按钮：平时隐形，悬停/聚焦才浮到图格右上 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
    position: absolute;
    top: 2px;
    right: 2px;
    display: flex;
    gap: 2px;
    opacity: 0;
    transition: none;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within .chatActions {
    opacity: 1;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatActions {
        opacity: 1;
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    margin: 0;
    padding: 0;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: rgba(255, 255, 255, 0.92);
    color: var(--mf-ink-2);
    font-size: 10px;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:hover {
        background-color: var(--mf-bg-hover);
        border-color: var(--mf-green);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 1px;
}

/* 置顶标记 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatPinned {
    top: 2px;
    left: 2px;
    color: var(--mf-title-2);
    opacity: 1;
}

/* 触屏没有 hover，按钮常显 */
@media (hover: none) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
        opacity: 1;
    }
}

/* ---------- 「更多聊天」：原站 .dede_pages 分页条 ---------- */
.welcomePanel .welcomeRecent .recentChatList .showMoreChats {
    flex: 1 0 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    width: 100%;
    height: 25px;
    margin: 4px 6px 0;
    padding: 0;
    border: none;
    border-top: 1px solid var(--mf-line-2);
    border-radius: 0;
    background-color: transparent;
    color: var(--mf-ink-2);
    font-size: 12px;
    letter-spacing: 0;
    transition: none;
}

/* 原生是 FontAwesome 图标，补一行文字提示这是「展开」 */
.welcomePanel .welcomeRecent .recentChatList .showMoreChats::after {
    content: "更多聊天";
    font-size: 12px;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .showMoreChats:hover {
        background-color: var(--mf-bg-hover);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeRecent .recentChatList .showMoreChats:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeRecent .recentChatList .showMoreChats:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: -1px;
}


/*
 * 加载页：接管 SillyTavern 的加载遮罩，复刻原站那句
 * 「正在载入,请稍候...」（连全角逗号一起搬）。
 *
 * 两条链路都要覆盖，否则切换时会闪一下默认样式：
 *   1. HTML 首屏的 <div id="preloader">（JS 还没跑起来时）
 *   2. 初始化后由 action-loader.js 创建的
 *      <dialog class="popup transparent_dialogue_popup"> 内的 #loader.splash-screen
 */

/* 站名字标：位图宽高比由 01-logo.css 的 --mf-logo-ratio 提供（297 / 90 = 3.3） */
#preloader::before,
#loader #load-spinner {
    --mf-brand-h: 40px;
    --mf-brand-w: calc(var(--mf-brand-h) * var(--mf-logo-ratio));
}

/* ---------- 全屏遮罩 ---------- */
#preloader,
.popup.transparent_dialogue_popup:has(#loader) {
    background-color: var(--mf-bg-soft);
    background-image: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* 首屏还没创建 #loader 时，至少先给出站名 */
#preloader::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: var(--mf-brand-w);
    height: var(--mf-brand-h);
    transform: translate(-50%, -50%);
    background-image: var(--mf-logo);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

/* 加载 Popup 本身：铺满视口、去掉弹窗边框与内边距 */
.popup.transparent_dialogue_popup:has(#loader) {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    width: 100dvw !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    overflow: hidden !important;
}

.popup:has(#loader) :is(.popup-body, .popup-content) {
    width: 100%;
    height: 100%;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* ---------- 居中块：一个 dl.tbox ---------- */
#loader {
    position: fixed !important;
    inset: auto !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%);
    /* loader.css 的 #loader.splash-screen 有 width:100%，特异性更高，必须压过去 */
    width: min(360px, 88vw) !important;
    height: auto !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 26px 22px 22px;
    display: flex !important;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    /* loader.css 里 #loader.splash-screen 有 gap: 4rem，必须压掉 */
    gap: 0 !important;
    border: 1px solid var(--mf-line);
    border-top: 3px solid var(--mf-title);
    border-radius: 0;
    background: var(--mf-paper);
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.65);
    color: var(--mf-ink);
    font-family: var(--mf-font);
    overflow: clip;
}

/* 酒馆自带的 SillyTavern logo 不要 */
#loader .splash-logo {
    display: none !important;
}

/* 站名字标替换掉原生旋转齿轮 */
#loader #load-spinner {
    position: relative !important;
    top: auto !important;
    left: auto !important;
    order: 1;
    width: var(--mf-brand-w) !important;
    height: var(--mf-brand-h) !important;
    margin: 0 0 14px;
    font-size: 0 !important;
    color: transparent !important;
    animation: none;
    background-image: var(--mf-logo);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

#loader #load-spinner::before,
#loader #load-spinner::after {
    content: none !important;
}

/* 主文案：原站那句加载提示 */
#loader::before {
    content: "正在载入,请稍候...";
    order: 2;
    color: var(--mf-title-2);
    font: 700 13px/1.5 var(--mf-font);
    letter-spacing: 2px;
}

/* 副文案：沿用酒馆原生文案，只统一字体与颜色 */
#loader .splash-message {
    order: 3;
    margin: 6px 0 0;
    color: var(--mf-ink-4);
    font: 400 11.5px/1.6 var(--mf-font) !important;
    letter-spacing: 0;
    opacity: 1;
}

/* 细进度条：1px 轨道上滑过一小段绿色 */
#loader::after {
    content: "";
    order: 4;
    width: 180px;
    height: 1px;
    margin-top: 16px;
    background-color: var(--mf-line-2);
    background-image: linear-gradient(90deg, var(--mf-title-2) 0 44px, transparent 44px);
    background-repeat: no-repeat;
    background-position: -44px 0;
    animation: mf-loading-bar 1.3s linear infinite;
}

@keyframes mf-loading-bar {
    from { background-position: -44px 0; }
    to { background-position: 180px 0; }
}

@media (prefers-reduced-motion: reduce) {
    #loader::after {
        animation: none !important;
        background-position: 0 0;
    }
}

/* 窄屏下收一圈 */
@media (max-width: 640px) {
    #loader {
        width: min(320px, 88vw) !important;
        padding: 22px 18px 18px;
    }

    #loader #load-spinner,
    #preloader::before {
        --mf-brand-h: 22px;
    }

    #loader::after {
        width: 150px;
    }
}


/*
 * 适配层：窄屏与移动端
 * 收边距、降字号、保证触摸目标；虚线列表与直角边框保持不变，不塌成现代卡片。
 */

@media (max-width: 640px) {
    html:root {
        --mf-title-size: 12.5px;
        --mf-body-size: 12.5px;
        --mf-comment-size: 12.5px;
        --mf-avatar: 20px;
        --mf-avatar-comment: 22px;
        --mf-titlebar-h: 26px;
        --mf-chat-gap: 6px;
        --mf-gutter: 6px;
    }

    /* 标题条：头像更小，左侧让位同步收窄 */
    #chat .mes[is_user="false"] .ch_name {
        padding-left: 34px;
        padding-right: 4px;
    }

    #chat .mes[is_user="false"] .mesAvatarWrapper {
        top: 3px;
        left: 6px;
    }

    #chat .mes[is_user="false"] .mes_text {
        padding: 7px 9px 8px;
    }

    #chat .mes[is_user="true"] {
        padding: 5px 9px 6px;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        top: 5px;
        left: 9px;
    }

    #chat .mes[is_user="true"] .ch_name {
        padding-left: 30px;
    }

    #chat .mes_reasoning_details {
        margin: 0 9px 6px;
    }

    #chat .mes[is_user="false"] .mes_block::after {
        margin: 0 9px 6px;
    }

    /* 输入区整条收窄，按钮仍保持可点 */
    #form_sheld {
        padding: 4px 6px 5px;
    }

    #nonQRFormItems {
        padding: 2px 3px;
    }

    /* 发表评论按钮缩到 56px，给 textarea 留位置 */
    #send_but:not(.displayNone),
    #mes_stop:not(.displayNone) {
        width: 56px;
        height: 24px;
    }

    #mes_stop {
        width: 56px !important;
        height: 24px !important;
    }

    #rightSendForm > div#send_but {
        width: 56px;
        min-width: 56px;
    }

    #send_but::before {
        letter-spacing: 0;
    }

    #options_button,
    #leftSendForm .interactable {
        width: 26px;
        height: 26px;
    }

    /* 顶栏：字标缩小，给图标让位 */
    #top-settings-holder {
        padding: 0 66px 0 88px;
    }

    #top-settings-holder::before {
        left: 6px;
        width: 78px;
        height: 22px;
        background-size: auto 22px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 6px;
    }

    #rightNavDrawerIcon {
        width: 56px;
        height: 20px;
        padding: 0;
    }

    #rightNavDrawerIcon::after {
        font-size: 11px;
        letter-spacing: 0;
    }

    /* 欢迎页图格：小屏按 96×72 图框等比缩小，仍保持原站 126:136 的格子比例 */
    .welcomePanel .welcomeRecent .recentChatList {
        padding: 6px 0;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat {
        flex: 0 0 102px;
        max-width: 102px;
        height: 112px;
        padding: 0 0 0 4px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
        width: 98px;
        height: 76px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
        padding-top: 4px;
        font-size: 11.5px;
        line-height: 16px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
        padding-right: 0;
    }

    .welcomePanel .welcomeHeader {
        font-size: 11.5px;
    }

    .welcomePanel .welcomeShortcuts .menu_button {
        height: 20px;
        padding: 0 6px;
        font-size: 11px;
    }
}

@media (max-width: 500px) {
    /* 底部工具行在小屏只留两段，避免换行 */
    #chat .mes[is_user="false"] .mes_block::after {
        content: "分享　收藏　举报";
        font-size: 10.5px;
        letter-spacing: 0;
    }

    #chat .mes .swipes-counter {
        font-size: 10px;
    }

    /* 小屏顶栏只留字标与红按钮 */
    #top-settings-holder {
        padding: 0 60px 0 80px;
    }

    #top-settings-holder::before {
        width: 70px;
        height: 20px;
        background-size: auto 20px;
    }
}

/* 中等宽度：红按钮缩一号，右侧留白同步收窄 */
@media (min-width: 641px) and (max-width: 900px) {
    #top-settings-holder {
        padding: 0 78px 0 88px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 8px;
    }

    #rightNavDrawerIcon {
        width: 60px;
        height: 22px;
        padding: 0;
    }

    #rightNavDrawerIcon::after {
        font-size: 11.5px;
    }
}

/* 尊重系统「减少动态效果」 */
@media (prefers-reduced-motion: reduce) {
    #mes_stop,
    #loader::after {
        animation: none !important;
    }
}
